PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE IF NOT EXISTS "migrations" ("id" integer primary key autoincrement not null, "migration" varchar not null, "batch" integer not null);
CREATE TABLE IF NOT EXISTS "users" ("id" integer primary key autoincrement not null, "name" varchar not null, "email" varchar not null, "email_verified_at" datetime, "password" varchar not null, "role" varchar not null default 'staff', "office_id" integer, "remember_token" varchar, "created_at" datetime, "updated_at" datetime, foreign key("office_id") references "offices"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "password_reset_tokens" ("email" varchar not null, "token" varchar not null, "created_at" datetime, primary key ("email"));
CREATE TABLE IF NOT EXISTS "sessions" ("id" varchar not null, "user_id" integer, "ip_address" varchar, "user_agent" text, "payload" text not null, "last_activity" integer not null, primary key ("id"));
CREATE TABLE IF NOT EXISTS "cache" ("key" varchar not null, "value" text not null, "expiration" integer not null, primary key ("key"));
CREATE TABLE IF NOT EXISTS "cache_locks" ("key" varchar not null, "owner" varchar not null, "expiration" integer not null, primary key ("key"));
CREATE TABLE IF NOT EXISTS "jobs" ("id" integer primary key autoincrement not null, "queue" varchar not null, "payload" text not null, "attempts" integer not null, "reserved_at" integer, "available_at" integer not null, "created_at" integer not null);
CREATE TABLE IF NOT EXISTS "job_batches" ("id" varchar not null, "name" varchar not null, "total_jobs" integer not null, "pending_jobs" integer not null, "failed_jobs" integer not null, "failed_job_ids" text not null, "options" text, "cancelled_at" integer, "created_at" integer not null, "finished_at" integer, primary key ("id"));
CREATE TABLE IF NOT EXISTS "failed_jobs" ("id" integer primary key autoincrement not null, "uuid" varchar not null, "connection" text not null, "queue" text not null, "payload" text not null, "exception" text not null, "failed_at" datetime not null default CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS "queues" ("id" integer primary key autoincrement not null, "user_id" integer, "name" varchar not null, "number" integer not null, "status" varchar check ("status" in ('waiting', 'serving', 'done', 'skipped')) not null default 'waiting', "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "visitors" ("id" integer primary key autoincrement not null, "name" varchar not null, "contact_number" varchar not null, "id_number" varchar, "photo_path" varchar, "office_id" integer, "other_office" varchar, "previous_office_id" integer, "queue_number" integer, "ticket_number" varchar, "type" varchar check ("type" in ('student', 'visitor')) not null default 'visitor', "course_id" integer, "cashier_id" integer, "priority" tinyint(1) not null default '0', "status" varchar check ("status" in ('waiting', 'serving', 'done', 'skipped', 'transferred')), "created_at" datetime, "updated_at" datetime, foreign key("course_id") references "courses"("id") on delete set null, foreign key("office_id") references "offices"("id") on delete cascade, foreign key("previous_office_id") references "offices"("id") on delete set null, foreign key("cashier_id") references "users"("id") on delete set null);
CREATE TABLE IF NOT EXISTS "offices" ("id" integer primary key autoincrement not null, "name" varchar not null, "abbreviation" varchar not null, "priority_counter" integer not null default '0', "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "courses" ("id" integer primary key autoincrement not null, "name" varchar not null, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "staff_course" ("id" integer primary key autoincrement not null, "user_id" integer not null, "course_id" integer not null, foreign key("user_id") references "users"("id") on delete cascade, foreign key("course_id") references "courses"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "visitor_transfers" ("id" integer primary key autoincrement not null, "visitor_id" integer not null, "from_office_id" integer not null, "to_office_id" integer not null, "from_queue_number" integer not null, "to_queue_number" integer not null, "transferred_by" integer, "transferred_at" datetime not null, "created_at" datetime, "updated_at" datetime, foreign key("visitor_id") references "visitors"("id") on delete cascade, foreign key("from_office_id") references "offices"("id") on delete restrict, foreign key("to_office_id") references "offices"("id") on delete restrict, foreign key("transferred_by") references "users"("id") on delete set null);
DELETE FROM sqlite_sequence;
CREATE UNIQUE INDEX "users_email_unique" on "users" ("email");
CREATE INDEX "sessions_user_id_index" on "sessions" ("user_id");
CREATE INDEX "sessions_last_activity_index" on "sessions" ("last_activity");
CREATE INDEX "jobs_queue_index" on "jobs" ("queue");
CREATE UNIQUE INDEX "failed_jobs_uuid_unique" on "failed_jobs" ("uuid");
CREATE UNIQUE INDEX "queues_number_unique" on "queues" ("number");
CREATE UNIQUE INDEX "offices_name_unique" on "offices" ("name");
CREATE UNIQUE INDEX "offices_abbreviation_unique" on "offices" ("abbreviation");
CREATE UNIQUE INDEX "courses_name_unique" on "courses" ("name");
CREATE UNIQUE INDEX "staff_course_user_id_course_id_unique" on "staff_course" ("user_id", "course_id");
COMMIT;
